// Demo articles
// File: scripts/demo-blogs.mjs
//
// Six articles in each of the six categories the blog page filters by, so
// every filter returns a full grid instead of "No articles found".
//
// CATEGORY IDS ARE LOWERCASE AND FIXED. src/components/blog/BlogFilters.jsx
// matches `post.category` against exactly these six ids. An article filed under
// "Nutrition" instead of "nutrition" is invisible on the page -- which is how
// the first batch of seed data disappeared.
//
// Covers come from public/blog-covers/<category>.svg, generated by
// scripts/make-blog-covers.mjs. Set `image` on an article to override it.

const CATEGORIES = ["training", "nutrition", "technology", "wellness", "mindset", "progress"];

