const photoUrl = (id) => `https://images.unsplash.com/${id}?w=1200&h=675&fit=crop`;

const slug = (title) =>
  title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_|_$/g, "")
    .slice(0, 48);

export const blogs = CATEGORIES.flatMap((category) =>
  ARTICLES[category].map(([title, excerpt, author, readTime, sections]) => ({
    id: `demo_blog_${category}_${slug(title)}`,
    title,
    excerpt,
    author,
    category,
    readTime,
    // A photo where one suits the headline, the category cover otherwise.
    image: PHOTOS[title] ? photoUrl(PHOTOS[title]) : `/blog-covers/${category}.svg`,
    sections: sections.map(([heading, content]) => ({ heading, content })),
  }))
);

export const BLOG_CATEGORIES = CATEGORIES;
